### Example Usage

```csharp
public class Program
{
    public static void Main(string[] args)
    {
        // Create an instance of the AST Parser
        var astParser = new ASTParser();

        // Parse a SQL query
        var sqlQuery = "SELECT * FROM orders JOIN customers ON orders.customer_id = customers.customer_id";
        var ast = astParser.Parse(sqlQuery);

        // Create an instance of the Optimization Engine
        var optimizationEngine = new OptimizationEngine();

        // Optimize the query
        var optimizedPlan = optimizationEngine.Optimize(ast);

        // Create an instance of the Execution Plan Generator
        var executionPlanGenerator = new ExecutionPlanGenerator();

        // Generate the execution plan
        var executionPlan = executionPlanGenerator.GeneratePlan(optimizedPlan);

        // Print the execution plan
        Console.WriteLine("Execution Plan:");
        PrintExecutionPlan(executionPlan.Root, 0);
    }

    private static void PrintExecutionPlan(OperatorNode node, int level)
    {
        Console.WriteLine(new string(' ', level * 4) + node.OperatorType);
        if (node.Children != null)
        {
            foreach (var child in node.Children)
            {
                PrintExecutionPlan(child, level + 1);
            }
        }
    }
}
